# owner: platform
"""Contact sheet for substitute teachers."""

from typing import Iterable, List

from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _check(students: List[Student]) -> None:
    """Refuse an empty list or a student without email."""
    if not students:
        raise ProjectError("no students for contact sheet")
    # Name the first student who has no email on file
    for s in students:
        if not s.email:
            raise ProjectError(
                f"no email for {s.display_name}"
            )


def _widths(cells: List[tuple]) -> List[int]:
    return [max(len(c) for c in col) for col in zip(*cells)]


def contact_rows(students: Iterable[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    ordered = sorted(students, key=lambda s: s.display_name)
    _check(ordered)
    cells = [
        (s.display_name, s.section, s.email) for s in ordered
    ]
    w = _widths(cells)
    return [
        "  ".join(c.ljust(n) for c, n in zip(row, w)).rstrip()
        for row in cells
    ]
