        rows = contact_rows(
            [make("Zed", "Al"), make("Long", "Bo", "b@c.d", "B")]
        )
        self.assertEqual(
            rows, ["Long, Bo  B  b@c.d", "Zed, Al   A  x@y.z"]
        )

    def test_missing_email_names_student(self):
        with self.assertRaisesRegex(ProjectError, "Doe, Jo"):
